Given a head of linked list containing nodes with values 0, 1, and 2 only, rearrange the list so that all 0s appear first, followed by all 1s, and then all 2s at the end, while maintaining the relative order within each group.Examples:Input:  Output: 0 → 1  → 1  → 2  →2  → 2 → 2 → 2Explanation: All the 0s are segregated to the left end of the linked list, 2s to the right end of the list, and 1s in between. Input:  Output: 0 → 1 → 2 → 2Explanation: After arranging all the 0s, 1s and 2s in the given format, the output will be 0 -> 1 → 2 → 2. Try It YourselfTable of Content[Naive Approach] Using an Extra Array - O(n × log n) Time and O(n) Space[Expected Approach - 1] Using Count of 0s, 1s and 2s - O(n) Time and O(1) Space[Expected Approach - 2] By Changing Links of Nodes - O(n) Time and O(1) Space[Expected Approach - 3] Using Dutch National Flag Algorithm - O(n) Time and O(1) Space[Naive Approach] Using an Extra Array - O(n × log n) Time and O(n) SpaceThe idea is to first convert the linked list into an array to easily leverage sorting, as sorting an array is straightforward and efficient. After sorting the array, we traverse the linked list again and reassign the sorted values back to the nodes. 
            C++

    #include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

class Node {
public:
    int data;
    Node* next;

    Node(int new_data) {
        data = new_data;
        next = nullptr;
    }
};

Node* segregate(Node* head) {
    if (!head || !(head->next)) 
        return head; 

    // convert linked list to array
    vector<int> arr;
    Node* curr = head;
    while (curr) {
        arr.push_back(curr->data);
        curr = curr->next;
    }

    // sort the array 
    sort(arr.begin(), arr.end());

    // reassign sorted values back to the linked list
    curr = head;
    for (int i = 0; i < arr.size(); i++) {
        curr->data = arr[i];
        curr = curr->next;
    }

    return head; 
} 

int main() {

    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(2);
    head->next->next->next = new Node(1);
    head->next->next->next->next = new Node(2);
    head->next->next->next->next->next = new Node(0);
    head->next->next->next->next->next->next = new Node(2);
    head->next->next->next->next->next->next->next = new Node(2);

    head = segregate(head);

    while (head != nullptr) {
        cout << head->data;
        if(head->next != nullptr){
            cout << " -> ";
        }
        head = head->next;
    }
    cout << "\n";
    return 0;
}


