        data = new_data;
        next = nullptr;
    }
};

Node* segregate(Node* head) {
    if (!head || !(head->next)) 
        return head; 

    // Initialize counts for 0s, 1s, and 2s
    int cntZero = 0, cntOne = 0, cntTwo = 0;

    // Traverse the list to
    // count the occurrences of 0, 1, and 2
    Node* curr = head;
    while (curr) {
        if (curr->data == 0) {
            cntZero++;
        } else if (curr->data == 1) {
            cntOne++;
        } else {
            cntTwo++;
        }
        curr = curr->next;
    }

    // Rebuild the list with sorted values
    curr = head;

    // First add all the 0s
    while (cntZero--) {
        curr->data = 0;
        curr = curr->next;
    }

    // Then add all the 1s
    while (cntOne--) {
        curr->data = 1;
        curr = curr->next;
    }

    // Finally add all the 2s
    while (cntTwo--) {
        curr->data = 2;
        curr = curr->next;
    }

    return head; 
} 

