class Node {
public:
    int data;
    Node* next;

    Node(int new_data) {
        data = new_data;
        next = nullptr;
    }
};

Node* segregate(Node* head) {
	if (!head || !(head->next)) 
		return head; 

	Node* zeroD = new Node(0); 
	Node* oneD = new Node(0); 
	Node* twoD = new Node(0);

	Node *zero = zeroD, *one = oneD, *two = twoD; 

	// traverse list 
	Node* curr = head; 
	while (curr) { 
		if (curr->data == 0) { 

          	// if the data of current node is 0, 
      		// append it to pointer zero and update zero
			zero->next = curr; 
			zero = zero->next; 
		} 
		else if (curr->data == 1) { 

          	// if the data of current node is 1, 
      		// append it to pointer one and update one
			one->next = curr; 
			one = one->next; 
		} 
		else { 
          	// if the data of current node is 2, 
      		// append it to pointer two and update two
			two->next = curr; 
			two = two->next; 
		} 
		curr = curr->next; 
	} 

	// combine the three lists
	zero->next = (oneD->next) ? (oneD->next) : (twoD->next); 
	one->next = twoD->next; 
	two->next = NULL; 

	// updated head 
	head = zeroD->next; 

	delete zeroD; 
	delete oneD; 
	delete twoD; 

	return head; 
} 

